// 测试程序：验证"生日"(海淀真题 b4194)考生程序的正确性
// 用法： g++ -O2 -o judge_b4194 judge_b4194.cpp && ./judge_b4194 <考生二进制程序路径>
// 本题有多种合法排列：校验 (1) 输出是输入的一个重排；(2) 环形相邻身高差最大值等于该样例的最优值。
#include <cstdio>
#include <cstdlib>
#include <string>
#include <vector>
#include <map>
#include <sstream>
#include <fstream>
#include <algorithm>
#include <cstdlib>
#include <iostream>
#include <unistd.h>

static std::string runProgram(const std::string& exePath, const std::string& input) {
    std::string inFile = "/tmp/oa1_b4194_in_" + std::to_string(getpid()) + ".txt";
    std::string outFile = "/tmp/oa1_b4194_out_" + std::to_string(getpid()) + ".txt";
    { std::ofstream fin(inFile); fin << input; }
    std::string cmd = "\"" + exePath + "\" < \"" + inFile + "\" > \"" + outFile + "\" 2>/dev/null";
    int rc = system(cmd.c_str());
    (void)rc;
    std::ifstream fout(outFile);
    std::stringstream ss;
    ss << fout.rdbuf();
    std::remove(inFile.c_str());
    std::remove(outFile.c_str());
    return ss.str();
}

struct Case { std::string input; long long n; long long optimal; };

int main(int argc, char** argv) {
    if (argc < 2) { std::cerr << "用法: " << argv[0] << " <考生二进制程序路径>\n"; return 1; }
    std::string exePath = argv[1];
    // optimal：样例输入对应的"最小化的最大环形相邻身高差"，由暴力/参考解法预先算出
    std::vector<Case> cases = {
        {"5\n2 1 1 3 2\n", 5, 1},
        {"3\n30 10 20\n", 3, 20},
    };
    int total = (int)cases.size(), passed = 0;
    std::vector<int> failedIdx;
    std::vector<std::string> detail(total);
    for (int t = 0; t < total; t++) {
        std::stringstream ins(cases[t].input);
        long long n = cases[t].n;
        std::vector<long long> expect(n);
        { long long dummy; ins >> dummy; }  // 跳过输入的第一行 n
        for (long long i = 0; i < n; i++) ins >> expect[i];
        std::string out = runProgram(exePath, cases[t].input);
        std::stringstream oss(out);
        std::vector<long long> got(n);
        bool ok = true;
        for (long long i = 0; i < n; i++) {
            if (!(oss >> got[i])) { ok = false; break; }
        }
        if (ok && oss.peek() != EOF) {
            // 允许末尾多余空白，但不应有多余数字
            int ch;
            while ((ch = oss.peek()) != EOF) { if (ch != ' ' && ch != '\t' && ch != '\n' && ch != '\r') { ok = false; break; } oss.get(); }
        }
        if (ok) {
            std::vector<long long> a = expect, b = got;
            std::sort(a.begin(), a.end()); std::sort(b.begin(), b.end());
            if (a != b) ok = false;
        }
        if (ok) {
            long long mx = 0;
            for (long long i = 0; i < n; i++)
                mx = std::max(mx, std::llabs(got[i] - got[(i+1)%n]));
            if (mx != cases[t].optimal) { ok = false; detail[t] = "最大环形相邻差 " + std::to_string(mx) + " != 最优 " + std::to_string(cases[t].optimal); }
        } else {
            detail[t] = "输出不是输入的重排或格式错误";
        }
        if (ok) passed++; else failedIdx.push_back(t);
    }
    printf("=== 生日 测试结果：%d / %d 通过 ===\n", passed, total);
    if (!failedIdx.empty()) {
        printf("\n以下样例不符合预期：\n");
        for (int idx : failedIdx) printf("第 %d 组：%s\n", idx + 1, detail[idx].c_str());
    } else printf("全部样例通过！\n");
    return failedIdx.empty() ? 0 : 1;
}

