// 浮点答案：按绝对误差/相对误差 <= 1e-6 判定。
#include <cstdio>
#include <cstdlib>
#include <string>
#include <vector>
#include <sstream>
#include <fstream>
#include <iostream>
#include <unistd.h>

static std::string trim(const std::string& s) {
    size_t a = s.find_first_not_of(" \t\r\n");
    if (a == std::string::npos) return "";
    size_t b = s.find_last_not_of(" \t\r\n");
    return s.substr(a, b - a + 1);
}
static std::string runProgram(const std::string& exePath, const std::string& input) {
    std::string inFile = "/tmp/oa1_b4196_in_" + std::to_string(getpid()) + ".txt";
    std::string outFile = "/tmp/oa1_b4196_out_" + std::to_string(getpid()) + ".txt";
    { std::ofstream fin(inFile); fin << input; }
    std::string cmd = "\"" + exePath + "\" < \"" + inFile + "\" > \"" + outFile + "\" 2>/dev/null";
    int rc = system(cmd.c_str());
    (void)rc;
    std::ifstream fout(outFile);
    std::stringstream ss; ss << fout.rdbuf();
    std::remove(inFile.c_str()); std::remove(outFile.c_str());
    return ss.str();
}

struct Case { std::string input; std::vector<double> expected; };

static bool closeD(double a, double b) {
    double d = a > b ? a - b : b - a;
    double scale = b > 1 ? b : 1;
    return d <= 1e-6 * scale;
}

int main(int argc, char** argv) {
    if (argc < 2) { std::cerr << "用法: " << argv[0] << " <考生二进制程序路径>\n"; return 1; }
    std::string exePath = argv[1];
    std::vector<Case> cases = {
        {"5\n2 10\n1 9\n1 10\n1\n5 7\n1 2 3 4 6\n2 1000000000\n413470354 982876160\n9 478\n1 10 25 33 239 445 453 468 477\n",
         {3.0, 3.666666666666667, 2.047619047619048, 329737645.75, 53.7}},
    };
    int total = (int)cases.size(), passed = 0;
    std::vector<int> failedIdx;
    std::vector<std::string> actualOutputs(total);
    for (int i = 0; i < total; i++) {
        std::string out = runProgram(exePath, cases[i].input);
        actualOutputs[i] = trim(out);
        std::stringstream ss(out);
        std::vector<double> got;
        double v;
        while (ss >> v) got.push_back(v);
        bool ok = got.size() == cases[i].expected.size();
        for (size_t j = 0; ok && j < got.size(); j++) if (!closeD(got[j], cases[i].expected[j])) ok = false;
        if (ok) passed++; else failedIdx.push_back(i);
    }
    printf("=== 赛车游戏 测试结果：%d / %d 通过 ===\n", passed, total);
    if (!failedIdx.empty()) {
        printf("\n以下样例不符合预期：\n");
        for (int idx : failedIdx) printf("第 %d 组实际输出：%s\n", idx + 1, actualOutputs[idx].c_str());
    } else printf("全部样例通过！\n");
    return failedIdx.empty() ? 0 : 1;
}
